    const rawData = item.json.data || '';
    // Remove whitespace and parse stringified JSON into an object
    parsedTarget = JSON.parse(rawData.trim());
  } catch (error) {
    parsedTarget = { error: error.message };
  }

  return {
    json: {
      target: parsedTarget
    }
  };
});

// Process all incoming items from the n8n workflow execution
return $input.all().map(item => {
  const rawData = item.json.data || '';

  // Separate the string by newline characters, remove whitespace, and filter empty lines
  const stockSymbols = rawData
    .split(/\r?\n/)
    .map(symbol => symbol.trim())
    .filter(symbol => symbol.length > 0);

  // Return the structured output containing the array of symbols
  return {
    json: {
      vn30_stock_symbols: stockSymbols
    }
  };
});

return $input.all().map(item => {
  const dataset = item.json.data || [];
  const vn30Symbols = new Set(item.json.vn30_stock_symbols || []);

  const largeCapSymbols = [];
  const midCapSymbols = [];

  dataset.forEach(row => {
    const symbol = row.stock_key;
    if (!symbol) return;

    if (vn30Symbols.has(symbol)) {
      if (!largeCapSymbols.includes(symbol)) {
        largeCapSymbols.push(symbol);
      }
    } else {
      if (!midCapSymbols.includes(symbol)) {
        midCapSymbols.push(symbol);
      }
    }
  });

  return {
    json: {
      large_cap: largeCapSymbols,
      mid_cap: midCapSymbols
    }
  };
});

