const results = [];

// Check and add large_cap branch if symbols exist
if (inputData.large_cap && inputData.large_cap.length > 0) {
  results.push({
    json: {
      total_investment: inputData.allocateLargeCap/1000,
      selected_symbols: inputData.large_cap
    }
  });
}

// Check and add mid_cap branch if symbols exist
if (inputData.mid_cap && inputData.mid_cap.length > 0) {
  results.push({
    json: {
      total_investment: inputData.allocateMidCap/1000,
      selected_symbols: inputData.mid_cap
    }
  });
}

return results;
